COPY={}
def page(n,en,es,se,ss,ce,cs,fe=None,fs=None):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe or []),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs or [])}
page(16,('Doberman Deals subscription box: coming soon','Our Doberman subscription box is in development. Join the launch-update list to hear when confirmed details are available; no purchase or reservation is required.'),('Caja Doberman Deals: próximamente','Nuestra caja para dóberman está en desarrollo. Apúntate para recibir novedades cuando haya detalles confirmados; no exige compra ni reserva.'),[('Know what is available today','The launch-update signup is available now. The box is not currently offered for purchase on this site. Signing up adds your email to the launch-update list; it does not place an order, reserve stock or start a paid subscription.'),('Wait for confirmed box details','Contents, pricing, launch timing and delivery availability are not yet confirmed here. Rather than promising a particular item or a shipping destination, we will provide the confirmed offer before any purchase decision. Photographs on these pages illustrate life with a Doberman, not a finished box.'),('Choose whether to receive updates','The signup asks for an email address and your agreement to launch updates. Read the privacy notice before choosing. You can continue using our guides without joining the list, and submitting the form does not create a payment obligation.'),('Use practical guides while you wait','Our equipment, grooming and daily-routine guides can help you plan your dog’s current needs independently of a future box. Choose items and activities for your individual dog instead of delaying necessary care for a launch announcement.')],[('Qué hay disponible hoy','Puedes apuntarte a novedades. La caja aún no se vende en este sitio. La inscripción no hace un pedido, reserva existencias ni inicia una suscripción de pago.'),('Detalles que deben confirmarse','Contenido, precio, fecha de lanzamiento y zonas de entrega no están confirmados aquí. Presentaremos la oferta antes de cualquier compra. Las fotografías muestran convivencia con un dóberman, no una caja terminada.'),('Elige recibir novedades','Solicitamos correo y consentimiento para novedades. Lee la privacidad antes de elegir. Puedes utilizar las guías sin apuntarte; el formulario no genera obligaciones de pago.'),('Utiliza las guías mientras esperas','Las guías de equipo, higiene y rutina ayudan con necesidades actuales. Elige cuidados según tu perro, sin retrasarlos por un anuncio de lanzamiento.')],[],[],[('Can I order the box now?','Not yet. The launch-update signup is available, and confirmed purchase details will be provided before orders open.'),('Does signing up reserve a box?','No. It records your request for launch updates, not a purchase or stock reservation.')],[('¿Puedo comprarla ahora?','Todavía no. Puedes apuntarte a novedades; presentaremos los detalles antes de abrir pedidos.'),('¿La inscripción reserva una caja?','No. Registra tu solicitud de novedades, no una compra ni reserva de existencias.')])
page(129,('Hear when Doberman Deals is ready to launch','Join the email list for launch updates about our coming-soon subscription box. We ask for your email and consent; there is no checkout or payment.'),('Recibe novedades del lanzamiento de Doberman Deals','Apúntate por correo para recibir novedades de nuestra futura caja. Solicitamos correo y consentimiento; no hay compra ni pago.'),[('Choose an email you can access','Enter the address where you want to receive launch updates. Check the spelling before submitting. We do not ask for a delivery address, card details or information about your dog’s health to join this list.'),('Understand your choice','Tick the consent box only if you want Doberman Deals launch updates by email. The privacy notice explains the information collected and how to contact us about it. Reading the guides and learning about the box do not require signing up.'),('Look for a saved confirmation','Complete the security check if requested, then submit the form. A successful confirmation means the server saved your signup. If a security or saving error appears, your signup has not been confirmed; follow the message and try again when appropriate.'),('Keep launch expectations clear','The box is coming soon. Your signup is not an order, payment, stock reservation or guarantee of availability in your location. Confirmed contents, pricing and delivery details will be shared before a purchase decision.')],[('Elige un correo accesible','Escribe dónde quieres recibir novedades y revisa la dirección. No pedimos domicilio, tarjeta ni datos de salud del perro para esta lista.'),('Comprende tu elección','Marca consentimiento solo si deseas novedades por correo. La privacidad explica datos y contacto. Leer las guías o conocer la caja no exige inscripción.'),('Comprueba la confirmación','Completa la comprobación de seguridad si se solicita y envía. La confirmación significa que el servidor guardó la inscripción. Un error de seguridad o guardado no confirma tu registro; sigue el mensaje.'),('Mantén claras las expectativas','La caja llegará próximamente. Inscribirse no es pedido, pago, reserva ni garantía de disponibilidad local. Presentaremos contenido, precio y entrega confirmados antes de comprar.')],[],[],[('Is this a paid subscription?','No. This form requests launch updates by email; it does not take payment or create an order.'),('What if the form shows an error?','Wait for a successful saved confirmation before assuming you joined. Follow the security or saving message and retry when appropriate.')],[('¿Es una suscripción de pago?','No. Solicita novedades por correo, sin pago ni pedido.'),('¿Y si aparece un error?','Espera la confirmación de guardado antes de asumir que estás inscrito. Sigue el mensaje y vuelve a intentar cuando corresponda.')])
page(59,('Suspected bloat or GDV: seek emergency veterinary care','If you suspect bloat or gastric dilatation-volvulus (GDV), contact an emergency veterinarian and arrange immediate assessment. Do not wait for every sign or an online diagnosis.'),('Sospecha de dilatación o torsión gástrica: busca urgencias','Si sospechas dilatación-torsión gástrica, contacta con urgencias veterinarias y organiza valoración inmediata. No esperes todos los signos ni un diagnóstico de internet.'),[('Recognize concerning signs without self-diagnosing','Repeated attempts to vomit without bringing anything up, a swelling abdomen, restlessness or marked distress can be concerning. Weakness or collapse is also urgent. Signs can vary and are not a home diagnostic test; uncertainty is a reason to contact a veterinarian, not to wait for a complete checklist.'),('Contact the emergency clinic and go','Tell the clinic what you observed and when it started while arranging transport. Confirm the destination and follow the team’s instructions. If another person is available, ask them to handle the call or records so help is not delayed by searching for information.'),('Leave treatment to the veterinary team','Do not attempt stomach decompression, force vomiting or give a home remedy. Ask the emergency team what to do during transport. This page provides an action route to professional care, not a technique for treating suspected GDV at home.'),('Prepare the contact plan before an emergency','At a routine time, save your clinic and appropriate emergency facility’s contact details and confirm their location and arrangements. Share them with caregivers. Keep identification and medication details accessible; the preparation checklist below is for planning ahead, not delaying urgent care.'),('Discuss future risk after urgent concerns are addressed','Ask your veterinarian about individual risk and whether a preventive gastropexy conversation is appropriate. That is a separate planning discussion, not a response to current warning signs. Do not replace assessment of a suspected emergency with feeding changes or future prevention research.')],[('Observa sin diagnosticar en casa','Intentos repetidos de vomitar sin expulsar, abdomen aumentado, inquietud o angustia intensa pueden preocupar. Debilidad o colapso también son urgentes. Los signos varían: la duda justifica consultar, no esperar una lista completa.'),('Contacta y acude a urgencias','Explica lo observado y su inicio mientras organizas traslado. Confirma destino y sigue instrucciones. Otra persona puede gestionar llamada o registros para evitar retrasos.'),('Deja el tratamiento al equipo','No intentes descomprimir el estómago, provocar vómito ni dar remedios caseros. Consulta instrucciones de traslado. La página orienta hacia ayuda, sin enseñar tratamiento doméstico.'),('Prepara contactos con antelación','En un momento tranquilo guarda clínica y urgencias adecuadas, confirmando lugar y funcionamiento. Comparte con cuidadores y conserva identificación y medicamentos. La lista es para preparación, no para retrasar atención.'),('Consulta prevención después','Habla de riesgo individual y posible gastropexia preventiva con tu veterinario cuando se hayan atendido preocupaciones urgentes. No sustituye valorar signos actuales ni justifica esperar mientras investigas prevención.')],['Save verified emergency clinic contacts in advance.','Confirm the route and care arrangements.','Keep identification and medication details accessible.','Share the plan with caregivers.'],['Guarda contactos de urgencias verificados.','Confirma ruta y funcionamiento.','Conserva identificación y medicamentos.','Comparte el plan con cuidadores.'],[('Should I wait for the belly to look swollen?','Do not wait for every sign if you suspect an emergency. Contact an emergency veterinarian and arrange immediate assessment.')],[('¿Debo esperar a ver el abdomen hinchado?','No esperes todos los signos si sospechas una urgencia. Contacta con un veterinario de urgencias y organiza valoración inmediata.')])
